/**
 * Round 14 (R12): the twelfth independent check's method, on its own 441 held lines
 * (fixtures/a1125-check12-remedy-cases.json, generated by its a-remedy.mjs). Each remedy is
 * followed mechanically, at most six steps: the named part removed or written in the form named
 * (an option named alone loses its value too, where the case wrote one), a dependency_check call
 * answered proceed as the server records it. Each line must end allowed with every operand and
 * placement flag it was written with (a part the remedy named exactly may go), or in the general
 * remedy class. Zero lost packages, zero remedies naming text not in the command, zero loops.
 */

import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { afterEach, beforeEach, describe, expect, it } from "vitest";

import { sandbox, type HookRun, type Sandbox } from "./helpers/a1123-hookfix-run.js";
import { followRemedy, record } from "./helpers/a1125-hook-run.js";

interface Case {
  cmd?: string;
  ps?: string;
  keep: string[];
  vars?: Record<string, string>;
}
const CASES: Case[] = JSON.parse(readFileSync(join(dirname(fileURLToPath(import.meta.url)), "fixtures", "a1125-check12-remedy-cases.json"), "utf8"));

let s: Sandbox;
beforeEach(() => {
  s = sandbox();
  s.ledger([]);
});
afterEach(() => s.dispose());

/** The general remedies: no single part to name. */
const GENERAL = [/Run the install as a plain command of its own/, /sed and awk can run a command/, /run the make target/, /each package a separate argument/, /retype it with plain spaces/];

/** The name alone of an operand as written (the check's own nameAlone). */
function nameAlone(tok: string): string {
  const t = tok.replace(/^['"]|['"]$/g, "");
  if (t.startsWith("@")) {
    const i = t.indexOf("@", 1);
    return i > 0 ? t.slice(0, i) : t;
  }
  return /^([A-Za-z0-9][A-Za-z0-9._/~-]*?)(?:\[[^\]]*\])?(?=[@=<>!~;\s(]|$)/.exec(t)?.[1] ?? t;
}

/** Answers the call a denial names, as the server records it. */
function answer(r: HookRun): void {
  record(
    s,
    (r.items ?? []).map((i) => {
      // (round 20, Q1: a crates.io bare version is the caret range, recorded with requested: the version itself)
      if (i.ecosystem === "crates.io" && /^v?\d+\.\d+\.\d+$/.test(i.to)) return { ecosystem: i.ecosystem, package: i.package, version: i.to, verdict: "proceed", requested: i.to };
      const exact = /^(?:==)?v?\d+(?:\.\d+)*$/.test(i.to) || i.to === "latest";
      return { ecosystem: i.ecosystem, package: i.package, version: exact && i.to !== "latest" ? i.to.replace(/^==/, "") : "9.9.9", verdict: "proceed", ...(exact && i.to !== "latest" ? {} : { requested: i.to }) };
    }),
  );
}

function follow(c: Case): { end: string; final: string; named: string[] } {
  const tool = c.ps !== undefined ? "PowerShell" : "Bash";
  let cmd = c.ps ?? c.cmd ?? "";
  const named: string[] = [];
  const seen = new Set<string>();
  const value = Object.values(c.vars ?? {})[0] ?? "x";
  for (let step = 0; step < 6; step++) {
    const r = s.run({ session_id: "s", cwd: s.project, hook_event_name: "PreToolUse", tool_name: tool, tool_input: { command: cmd } });
    if (r.decision !== "deny") return { end: "allow", final: cmd, named };
    const key = `${cmd}\0${r.text.slice(0, 300)}`;
    if (seen.has(key)) return { end: "LOOP", final: cmd, named };
    seen.add(key);
    if (/answered (?:avoid|wait)/.test(r.text)) return { end: "avoid", final: cmd, named };
    if (!r.text.includes("could not be read") && r.items && r.items.length > 0) {
      answer(r);
      continue;
    }
    if (GENERAL.some((g) => g.test(r.text))) return { end: "GENERAL", final: cmd, named };
    const part = /Run the same command (?:without the option `([^`]+)`|without `([^`]+)`|with `([^`]+)` written as)/.exec(r.text);
    if (!part) return { end: `OTHER: ${r.text.slice(0, 200)}`, final: cmd, named };
    const token = part[1] ?? part[2] ?? part[3];
    if (!cmd.includes(token)) return { end: `TOKEN-NOT-IN-COMMAND ${token}`, final: cmd, named };
    // The user knows an option's arity: here, the word after it is its value unless it is one the line is written for.
    const next = followRemedy(cmd, r.text, value, (_o, w) => w !== "" && !w.startsWith("-") && !c.keep.includes(w) && !c.keep.some((k) => w.startsWith(nameAlone(k))));
    if (next === null || next === cmd) return { end: `NOT-MECHANICAL ${token}`, final: cmd, named };
    named.push(token);
    cmd = next;
  }
  return { end: "OVER-6-STEPS", final: cmd, named };
}

describe("R12: the check's 441 held lines, each remedy followed mechanically", () => {
  it("the fixture holds the check's 441 lines", () => {
    expect(CASES.length).toBe(441);
  });
  it.each(CASES.map((c, i) => [i + 1, c.ps !== undefined ? "PS" : "SH", c.ps ?? c.cmd ?? "", c] as const))("#%i %s> %s", (_i, _d, _cmd, c) => {
    const r = follow(c);
    if (r.end === "GENERAL") return;
    expect(r.end, JSON.stringify(r)).toBe("allow");
    const words = r.final.split(/\s+/).map((w) => w.replace(/^['"]|['"]$/g, ""));
    for (const keep of c.keep) {
      const parts = keep.split(" ");
      const present = parts.every((p) => words.includes(p) || words.includes(nameAlone(p)) || r.final.includes(p));
      const namedExactly = r.named.some((t) => t === keep);
      expect(present || namedExactly, `${keep} kept in ${r.final} (named: ${r.named.join(" | ")})`).toBe(true);
    }
  });
});
